code.solution:
package main

import "fmt"

func double(a *[4]int) { // take a pointer to the array
	for i := range a {
		a[i] *= 2          // a[i] is shorthand for (*a)[i]
	}
}

func main() {
	nums := [4]int{1, 2, 3, 4}
	double(&nums)            // pass the address so the callee shares it
	fmt.Println(nums)        // [2 4 6 8]
}

